return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n > 1;','language'=>'id_ID','project-id-version'=>'babilim-0.1.0-id_ID-babilim-0.1.0-id_ID-20261030T025146','pot-creation-date'=>'2026-10-30T06:25:29+00:00','po-revision-date'=>'2026-10-30T06:25:29+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Melengkapi terjemahan yang hilang untuk plugin dan tema yang sudah terpasang di situs Anda.','Translations'=>'Terjemahan','Babilim Settings'=>'Pengaturan Babilim','Settings'=>'Pengaturan','You are not allowed to do this.'=>'Anda tidak diizinkan melakukan ini.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Pilih lebih sedikit komponen: maksimal %1$d operasi per proses (Anda memilih %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Komponen itu tidak terpasang di situs ini, sehingga terjemahan tidak dapat diminta untuknya.','Already installed.'=>'Sudah terpasang.','Downloaded and installed.'=>'Diunduh dan dipasang.','Babilim has not been enabled for this site yet.'=>'Babilim belum diaktifkan untuk situs ini.','No build is available to download for this locale.'=>'Tidak ada build yang tersedia untuk diunduh untuk lokal ini.','Rolled back to the previous build.'=>'Dikembalikan ke build sebelumnya.','Rolled back and reported.'=>'Dikembalikan dan dilaporkan.','Rolled back, but the report could not be sent: %s'=>'Dikembalikan, tetapi laporan tidak dapat dikirim: %s','Removed.'=>'Dihapus.','Translation requested.'=>'Terjemahan diminta.','This component was already uploaded. Babilim is checking it now.'=>'Komponen ini sudah diunggah. Babilim sedang memeriksanya sekarang.','Upload cancelled.'=>'Unggahan dibatalkan.','Upload complete — translation requested.'=>'Unggahan selesai — terjemahan diminta.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Komponen ini tidak mencantumkan nomor versi, sehingga terjemahan tidak dapat diminta untuknya.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Nomor versi komponen ini lebih panjang dari %d karakter, yang tidak dapat ditangani Babilim, sehingga terjemahan tidak dapat diminta untuknya.','A translation cannot be requested for that locale on this site right now.'=>'Terjemahan tidak dapat diminta untuk lokal itu di situs ini saat ini.','Thank you. Your report was sent.'=>'Terima kasih. Laporan Anda telah dikirim.','This report does not name a valid plugin or theme and locale.'=>'Laporan ini tidak menyebutkan nama plugin atau tema dan lokal yang valid.','Please choose a category for this report.'=>'Silakan pilih kategori untuk laporan ini.','This report is missing a valid build to report against.'=>'Laporan ini tidak memiliki build valid untuk dilaporkan.','This build is not one this site currently knows about for this component/locale.'=>'Build ini bukan build yang saat ini dikenali situs ini untuk komponen/lokal ini.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Kolom "%1$s" terlalu panjang: berisi %2$d karakter dan batasnya %3$d. Tidak ada yang dikirim; silakan persingkat lalu coba lagi.','Original string'=>'String asli','String context'=>'Konteks string','Current translation'=>'Terjemahan saat ini','Suggested translation'=>'Terjemahan yang disarankan','Note (optional)'=>'Catatan (opsional)','Where you saw this (optional)'=>'Di mana Anda melihat ini (opsional)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Sinkronisasi Babilim sementara tertunda oleh layanan (dibatasi laju); akan dicoba lagi setelah %s.','The locale you added is not valid: use a WordPress locale code such as ll_CC (letters, digits, underscore, hyphen or @,